class Solution:
    def maximumSum(self, edges: List[List[int]], nums: List[int], k: int) -> int:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        parent = [-1] * n
        order = [0]
        parent[0] = -2
        head = 0
        while head < len(order):
            u = order[head]; head += 1
            for v in adj[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)
        NEG = float('-inf')
        dp = [[[NEG] * 2 for _ in range(k + 1)] for _ in range(n)]
        for u in reversed(order):
            kids = [v for v in adj[u] if v != parent[u]]
            for d in range(k + 1):
                for p in range(2):
                    s = -1 if p else 1
                    best = nums[u] * s
                    for c in kids:
                        best += dp[c][min(d + 1, k)][p]
                    if d >= k:
                        alt = -nums[u] * s
                        for c in kids:
                            alt += dp[c][1][p ^ 1]
                        best = max(best, alt)
                    dp[u][d][p] = best
        return dp[0][k][0]

