    long long maximumSum(vector<vector<int>>& edges, vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<int> parent(n, -1), order;
        order.reserve(n);
        parent[0] = -2;
        order.push_back(0);
        for (size_t h = 0; h < order.size(); h++) {
            int u = order[h];
            for (int v : adj[u]) if (parent[v] == -1) { parent[v] = u; order.push_back(v); }
        }
        const long long NEG = LLONG_MIN;
        vector<array<array<long long, 2>, 51>> dp(n);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            vector<int> kids;
            for (int v : adj[u]) if (v != parent[u]) kids.push_back(v);
