class Solution {
    public long maximumSum(int[][] edges, int[] nums, int k) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        parent[0] = -2;
        order.add(0);
        for (int h = 0; h < order.size(); h++) {
            int u = order.get(h);
            for (int v : adj.get(u)) if (parent[v] == -1) { parent[v] = u; order.add(v); }
        }
        long NEG = Long.MIN_VALUE / 2;
        long[][][] dp = new long[n][k + 1][2];
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            List<Integer> kids = new ArrayList<>();
            for (int v : adj.get(u)) if (v != parent[u]) kids.add(v);
            for (int d = 0; d <= k; d++) {
                for (int p = 0; p < 2; p++) {
                    long s = p == 1 ? -1 : 1;
                    long best = (long) nums[u] * s;
                    for (int c : kids) best += dp[c][Math.min(d + 1, k)][p];
                    if (d >= k) {
                        long alt = -(long) nums[u] * s;
                        for (int c : kids) alt += dp[c][1][p ^ 1];
                        best = Math.max(best, alt);
                    }
                    dp[u][d][p] = best;
                }
            }
        }
        return dp[0][k][0];
    }
}

