var maximumSum = function(edges, nums, k) {
    const n = nums.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const parent = new Array(n).fill(-1);
    const order = [0];
    parent[0] = -2;
    for (let h = 0; h < order.length; h++) {
        const u = order[h];
        for (const v of adj[u]) if (parent[v] === -1) { parent[v] = u; order.push(v); }
    }
    const NEG = -Infinity;
    const dp = Array.from({length: n}, () =>
        Array.from({length: k + 1}, () => [NEG, NEG]));
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        const kids = adj[u].filter(v => v !== parent[u]);
        for (let d = 0; d <= k; d++) {
            for (let p = 0; p < 2; p++) {
                const s = p ? -1 : 1;
                let best = nums[u] * s;
                for (const c of kids) best += dp[c][Math.min(d + 1, k)][p];
                if (d >= k) {
                    let alt = -nums[u] * s;
                    for (const c of kids) alt += dp[c][1][p ^ 1];
                    best = Math.max(best, alt);
                }
                dp[u][d][p] = best;
            }
        }
    }
    return dp[0][k][0];
};
